00028     public static function getHttpHeaders($pingUrl)
00029     {
00030         if (function_exists('curl_version')) {
00031             $result = self::getCurlHttpHeaders($pingUrl);
00032         } else {
00033             $result = self::getFopenHttpHeaders($pingUrl);
00034         }
00035 
00036         if (!empty($result)) {
00037             $rebuildResult = array();
00038             foreach ($result as $row) {
00039                 $row = trim($row);
00040                 if (!empty($row)) {
00041                     $rebuildResult[] = $row;
00042                 }
00043             }
00044             $result = $rebuildResult;
00045 
00046             Log::debug('getHttpHeaders:');
00047             foreach ($result as $header) {
00048                 Log::debug('-> ' . $header);
00049             }
00050         }
00051 
00052         return $result;
00053     }
