00066     public static function getFopenHttpHeaders($url)
00067     {
00068         $result = array();
00069 
00070         $context = stream_context_create(array(
00071             'ssl' => array(
00072                 'verify_peer'       => false,
00073                 'verify_peer_name'  => false,
00074                 'allow_self_signed' => true,
00075             )
00076         ));
00077 
00078         $fp = @fopen($url, 'r', false, $context);
00079         if ($fp) {
00080             $meta   = stream_get_meta_data($fp);
00081             $result = isset($meta['wrapper_data']) ? $meta['wrapper_data'] : $result;
00082             fclose($fp);
00083         }
00084 
00085         return $result;
00086     }
