00099     public static function getCurlHttpHeaders($url)
00100     {
00101         $result = array();
00102 
00103         $ch = curl_init();
00104         curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
00105         curl_setopt($ch, CURLOPT_VERBOSE, true);
00106         curl_setopt($ch, CURLOPT_HEADER, true);
00107         curl_setopt($ch, CURLOPT_URL, $url);
00108         curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
00109         curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false);
00110 
00111         $response = @curl_exec($ch);
00112         if (empty($response)) {
00113             return $result;
00114         }
00115 
00116         Log::trace('getCurlHttpHeaders:' . $response);
00117         $responseHeaders = explode("\r\n\r\n", $response, 2);
00118         if (!isset($responseHeaders[0]) || empty($responseHeaders[0])) {
00119             return $result;
00120         }
00121 
00122         return explode("\n", $responseHeaders[0]);
00123     }
