00187     public static function getGithubUrl($type = 'user', $user = APP_GITHUB_USER, $repo = null, $branch = null, $path = null) {
00188         if (empty($user) || !is_string($user)) {
00189             return false;
00190         }
00191 
00192         // Encode as URL path segment (not query encoding)
00193         $user = rawurlencode($user);
00194 
00195         switch ($type) {
00196             case 'user':
00197                 return "https://github.com/{$user}";
00198 
00199             case 'repo':
00200                 if (empty($repo) || !is_string($repo)) {
00201                     return false;
00202                 }
00203                 $repo = rawurlencode($repo);
00204                 return "https://github.com/{$user}/{$repo}";
00205 
00206             case 'issues':
00207                 if (empty($repo) || !is_string($repo)) {
00208                     return false;
00209                 }
00210                 $repo = rawurlencode($repo);
00211                 return "https://github.com/{$user}/{$repo}/issues";
00212 
00213             case 'raw':
00214                 if (empty($repo) || empty($branch) || empty($path) || !is_string($repo) || !is_string($branch) || !is_string($path)) {
00215                     return false;
00216                 }
00217                 $repo = rawurlencode($repo);
00218                 $branch = rawurlencode($branch);
00219 
00220                 $path = ltrim($path, '/');
00221                 $segments = array_map('rawurlencode', explode('/', $path));
00222                 $pathEncoded = implode('/', $segments);
00223 
00224                 return "https://raw.githubusercontent.com/{$user}/{$repo}/{$branch}/{$pathEncoded}";
00225 
00226             default:
00227                 return false;
00228         }
00229     }
