00254     public static function getHeaders($host, $port, $ssl = false)
00255     {
00256         $result  = array();
00257         $context = stream_context_create(array(
00258             'ssl' => array(
00259                 'verify_peer'       => false,
00260                 'verify_peer_name'  => false,
00261                 'allow_self_signed' => true,
00262             )
00263         ));
00264 
00265         $fp = @stream_socket_client(($ssl ? 'ssl://' : '') . $host . ':' . $port, $errno, $errstr, 5, STREAM_CLIENT_CONNECT, $context);
00266         if ($fp) {
00267             $out    = fgets($fp);
00268             $result = explode(PHP_EOL, $out);
00269             @fclose($fp);
00270         }
00271 
00272         if (!empty($result)) {
00273             $rebuildResult = array();
00274             foreach ($result as $row) {
00275                 $row = trim($row);
00276                 if (!empty($row)) {
00277                     $rebuildResult[] = $row;
00278                 }
00279             }
00280             $result = $rebuildResult;
00281 
00282             Log::debug('getHeaders:');
00283             foreach ($result as $header) {
00284                 Log::debug('-> ' . $header);
00285             }
00286         }
00287 
00288         return $result;
00289     }
