00298     public static function getApiJson($url)
00299     {
00300         $header = self::setupCurlHeaderWithToken();
00301 
00302         $ch = curl_init();
00303         curl_setopt($ch, CURLOPT_SSLVERSION, CURL_SSLVERSION_TLSv1_2);
00304         curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
00305         curl_setopt($ch, CURLOPT_VERBOSE, false); // Set to false to avoid polluting logs unless needed
00306         curl_setopt($ch, CURLOPT_URL, $url);
00307         curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
00308         curl_setopt($ch, CURLOPT_SSL_VERIFYHOST, false);
00309         curl_setopt($ch, CURLOPT_HTTPHEADER, $header);
00310         $data = curl_exec($ch);
00311         if (curl_errno($ch)) {
00312             Log::error('CURL Error (' . curl_errno($ch) . '): ' . curl_error($ch) . ' (URL: ' . $url . ')');
00313         }
00314 
00315         $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
00316         if ($httpCode >= 400) {
00317             Log::error('HTTP Error ' . $httpCode . ' for URL: ' . $url);
00318         }
00319 
00320         // curl_close() is deprecated in PHP 8.5+ as it has no effect since PHP 8.0
00321         // The resource is automatically closed when it goes out of scope
00322         if (PHP_VERSION_ID < 80500) {
00323             curl_close($ch);
00324         }
00325 
00326         return $data === false ? '' : trim($data);
00327     }
