00336     public static function getLatestVersion($url)
00337     {
00338         $result = self::getApiJson($url);
00339         if (empty($result)) {
00340             Log::error('Cannot retrieve latest github info: empty result or error for URL: ' . $url);
00341 
00342             return null;
00343         }
00344 
00345         $resultArray = json_decode($result, true);
00346         if ($resultArray === null) {
00347             Log::error('Failed to decode JSON response from: ' . $url . '. Response snippet: ' . substr($result, 0, 100));
00348             return null;
00349         }
00350 
00351         if (isset($resultArray['tag_name']) && isset($resultArray['assets'][0]['browser_download_url'])) {
00352             $tagName     = $resultArray['tag_name'];
00353             $downloadUrl = $resultArray['assets'][0]['browser_download_url'];
00354             $name        = $resultArray['name'];
00355             Log::debug('Latest version tag name: ' . $tagName);
00356             Log::debug('Download URL: ' . $downloadUrl);
00357             Log::debug('Name: ' . $name);
00358 
00359             return ['version' => $tagName, 'html_url' => $downloadUrl, 'name' => $name];
00360         } else {
00361             Log::error('Tag name, download URL, or name not found in the response: ' . $result);
00362 
00363             return null;
00364         }
00365     }
